/* @lc app=leetcode id=1813 lang=kotlin */
class Solution { fun areSentencesSimilar(sentence1: String, sentence2: String): Boolean = sentence1.split(" ").let { s1 -> sentence2.split(" ").let { s2 -> (if (s1.size <= s2.size) s1 to s2 else s2 to s1).let { (smaller, larger) -> (0 until smaller.size).takeWhile { smaller[it] == larger[it] }.count().let { i -> i + (0 until smaller.size - i).takeWhile { smaller[smaller.size - 1 - it] == larger[larger.size - 1 - it] }.count() == smaller.size } } } } }